from __future__ import annotations

from typing import Any

from aod._internal.application.cache.cache import Cache


class NullCache(Cache):
    """No-op cache that discards all operations."""

    def get(self, key: str) -> Any: ...
    def set(self, key: str, value: Any, ttl: float | None = None) -> None: ...
    def delete(self, key: str) -> None: ...
    def _get(self, key_material: object) -> Any: ...
    def _set(self, *args: Any, **kwargs: Any) -> None: ...
    def _delete(self, *args: Any, **kwargs: Any) -> None: ...
    def _flush(self) -> None: ...
